package com.samlscope.runner.cases;
import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.time.*;import java.util.*;import com.samlscope.core.transcript.*;import com.samlscope.core.plan.*;import com.samlscope.core.run.Reachability;import com.samlscope.core.evaluation.*;import com.samlscope.runner.DefaultCaseContext;
class SimpleSamlPhpAuthenticationIdentityEvidenceTest{@TempDir Path directory;static final String RUN="run_00000000000000000000000000";DefaultCaseContext context(boolean complete){return new DefaultCaseContext(RUN,TargetRole.IDP,Clock.systemUTC(),TestPlan.Parameters.defaults(),TestPlan.Interaction.defaults(),Reachability.CONFIRMED,new TranscriptRecorder(){public List<TranscriptEntry> list(String r){return List.of();}public TranscriptEntry record(TranscriptInput i){throw new AssertionError();}public TranscriptEntry updateSamlAnalysis(String a,String b,Map<String,Object>s){throw new AssertionError();}},complete);}SimpleSamlPhpAuthenticationIdentityEvidence reader(){return new SimpleSamlPhpAuthenticationIdentityEvidence(directory,e->{throw new AssertionError();},r->new byte[0],r->Optional.empty());}
@Test void absentPreservesLegacy(){assertTrue(reader().evaluate(context(true)).isEmpty());assertFalse(reader().exists("../"+RUN));}
@Test void declarationDoesNotProveIdentity()throws Exception{var p=Files.createDirectory(directory.resolve(RUN));Files.writeString(p.resolve("manifest.json"),"{\"identity_established\":true,\"ambient_disabled\":true}");assertEquals(Outcome.NOT_VERIFIED,reader().evaluate(context(true)).orElseThrow().outcome());}
@Test void ownedFileAndSymlinkFailClosed()throws Exception{var p=Files.writeString(directory.resolve(RUN),"{}");assertTrue(reader().exists(RUN));assertEquals(Outcome.NOT_VERIFIED,reader().evaluate(context(true)).orElseThrow().outcome());Files.delete(p);Files.createSymbolicLink(p,Files.createDirectory(directory.resolve("foreign")));assertTrue(reader().exists(RUN));assertEquals(Outcome.NOT_VERIFIED,reader().evaluate(context(true)).orElseThrow().outcome());}
@Test void incompleteTranscriptNeverProvesIdentity()throws Exception{Files.createDirectory(directory.resolve(RUN));assertEquals(Outcome.NOT_VERIFIED,reader().evaluate(context(false)).orElseThrow().outcome());}}
